module find_positions (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [3:0] m,\n    input wire [3:0] p,\n    input wire [3:0] a0, a1, a2, a3, a4, a5, a6, a7,\n    input wire [3:0] a8, a9, a10, a11, a12, a13, a14, a15,\n    input wire [3:0] b0, b1, b2, b3, b4, b5, b6, b7,\n    output reg done,\n    output reg [3:0] count,\n    output reg [4:0] pos0, pos1, pos2, pos3, pos4, pos5, pos6, pos7,\n    output reg [4:0] pos8, pos9, pos10, pos11, pos12, pos13, pos14, pos15\n);\n\n// State definitions\nlocalparam [2:0] IDLE = 3'd0;\nlocalparam [2:0] PREPARE_B = 3'd1;\nlocalparam [2:0] CHECK_Q = 3'd2;\nlocalparam [2:0] INIT_WINDOW = 3'd3;\nlocalparam [2:0] CHECK_WINDOW = 3'd4;\nlocalparam [2:0] SLIDE = 3'd5;\nlocalparam [2:0] SORT = 3'd6;\nlocalparam [2:0] FINISH = 3'd7;\n\nreg [2:0] state;\nreg [2:0] next_state;\nreg [3:0] q;\nreg [3:0] j;\nreg [3:0] elem_count;\nreg [3:0] pos_count;\nreg [4:0] temp_pos [0:15];\nreg [2:0] freq_b [0:15];\nreg [2:0] freq_win [0:15];\nreg [3:0] a_vals [0:15];\nreg [3:0] b_vals [0:15];\nreg freq_match;\ninteger i;\n\nalways @(*) begin\n    // Map input arrays\n    a_vals[0] = a0;  a_vals[1] = a1;  a_vals[2] = a2;  a_vals[3] = a3;\n    a_vals[4] = a4;  a_vals[5] = a5;  a_vals[6] = a6;  a_vals[7] = a7;\n    a_vals[8] = a8;  a_vals[9] = a9;  a_vals[10] = a10; a_vals[11] = a11;\n    a_vals[12] = a12; a_vals[13] = a13; a_vals[14] = a14; a_vals[15] = a15;\n    \n    b_vals[0] = b0;  b_vals[1] = b1;  b_vals[2] = b2;  b_vals[3] = b3;\n    b_vals[4] = b4;  b_vals[5] = b5;  b_vals[6] = b6;  b_vals[7] = b7;\n    for (i = 8; i < 16; i = i + 1) b_vals[i] = 4'd0;\n    \n    // Frequency comparison\n    freq_match = 1'b1;\n    for (i = 0; i < 16; i = i + 1) begin\n        if (freq_b[i] != freq_win[i]) freq_match = 1'b0;\n    end\nend\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        done <= 1'b0;\n        count <= 4'd0;\n        pos0 <= 5'd0; pos1 <= 5'd0; pos2 <= 5'd0; pos3 <= 5'd0;\n        pos4 <= 5'd0; pos5 <= 5'd0; pos6 <= 5'd0; pos7 <= 5'd0;\n        pos8 <= 5'd0; pos9 <= 5'd0; pos10 <= 5'd0; pos11 <= 5'd0;\n        pos12 <= 5'd0; pos13 <= 5'd0; pos14 <= 5'd0; pos15 <= 5'd0;\n        q <= 4'd0;\n        j <= 4'd0;\n        elem_count <= 4'd0;\n        pos_count <= 4'd0;\n        for (i = 0; i < 16; i = i + 1) begin\n            temp_pos[i] <= 5'd0;\n            freq_b[i] <= 3'd0;\n            freq_win[i] <= 3'd0;\n        end\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    state <= PREPARE_B;\n                    q <= 4'd0;\n                    j <= 4'd0;\n                    pos_count <= 4'd0;\n                    for (i = 0; i < 16; i = i + 1) begin\n                        freq_b[i] <= 3'd0;\n                        freq_win[i] <= 3'd0;\n                    end\n                end\n            end\n            \n            PREPARE_B: begin\n                if (j < m) begin\n                    if (b_vals[j] < 16) freq_b[b_vals[j]] <= freq_b[b_vals[j]] + 3'd1;\n                    j <= j + 4'd1;\n                end else begin\n                    j <= 4'd0;\n                    state <= CHECK_Q;\n                end\n            end\n            \n            CHECK_Q: begin\n                if (q < p) begin\n                    if (n > q) begin\n                        elem_count <= ((n - q - 4'd1) / p) + 4'd1;\n                        state <= INIT_WINDOW;\n                        j <= 4'd0;\n                        for (i = 0; i < 16; i = i + 1) freq_win[i] <= 3'd0;\n                    end else begin\n                        q <= q + 4'd1;\n                    end\n                end else begin\n                    j <= 4'd0;\n                    state <= SORT;\n                end\n            end\n            \n            INIT_WINDOW: begin\n                if (j < m) begin\n                    if ((q + j*p) < 16 && a_vals[q + j*p] < 16)\n                        freq_win[a_vals[q + j*p]] <= freq_win[a_vals[q + j*p]] + 3'd1;\n                    j <= j + 4'd1;\n                end else begin\n                    j <= 4'd0;\n                    state <= CHECK_WINDOW;\n                end\n            end\n            \n            CHECK_WINDOW: begin\n                if (elem_count >= m && freq_match) begin\n                    if (pos_count < 16) begin\n                        temp_pos[pos_count] <= q + 5'd1;\n                        pos_count <= pos_count + 4'd1;\n                    end\n                end\n                if (elem_count > m) begin\n                    state <= SLIDE;\n                end else begin\n                    q <= q + 4'd1;\n                    state <= CHECK_Q;\n                end\n            end\n            \n            SLIDE: begin\n                if ((q + j*p) < 16 && a_vals[q + j*p] < 16)\n                    freq_win[a_vals[q + j*p]] <= freq_win[a_vals[q + j*p]] - 3'd1;\n                if ((q + (j+m)*p) < 16 && a_vals[q + (j+m)*p] < 16)\n                    freq_win[a_vals[q + (j+m)*p]] <= freq_win[a_vals[q + (j+m)*p]] + 3'd1;\n                j <= j + 4'd1;\n                elem_count <= elem_count - 4'd1;\n                state <= CHECK_WINDOW;\n            end\n            \n            SORT: begin\n                if (j < pos_count - 4'd1) begin\n                    if (temp_pos[j] > temp_pos[j+4'd1]) begin\n                        temp_pos[j] <= temp_pos[j+4'd1];\n                        temp_pos[j+4'd1] <= temp_pos[j];\n                    end\n                    j <= j + 4'd1;\n                end else begin\n                    state <= FINISH;\n                end\n            end\n            \n            FINISH: begin\n                count <= pos_count;\n                {pos0, pos1, pos2, pos3, pos4, pos5, pos6, pos7,\n                 pos8, pos9, pos10, pos11, pos12, pos13, pos14, pos15} <= \n                    {temp_pos[0], temp_pos[1], temp_pos[2], temp_pos[3],\n                     temp_pos[4], temp_pos[5], temp_pos[6], temp_pos[7],\n                     temp_pos[8], temp_pos[9], temp_pos[10], temp_pos[11],\n                     temp_pos[12], temp_pos[13], temp_pos[14], temp_pos[15]};\n                done <= 1'b1;\n                state <= IDLE;\n            end\n            \n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule